const fmt=n=>Number(n||0).toLocaleString('zh-TW');const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const time=()=>new Date().toLocaleString('zh-TW');const makeID=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);
